def natural_sort_strings(strings):
    """Return a new list of strings sorted in natural order.

    Splits each string into maximal ASCII-digit and non-digit runs.
    Digit runs are compared by integer value; non-digit runs by
    case-sensitive Unicode lexical order.  Text tokens sort before
    numeric tokens when their kinds differ.  Shorter equal-prefix
    token lists sort first; equal keys preserve input order.
    Empty strings are allowed; Unicode digits are treated as text.
    """
    def _key(s):
        if s == "":
            return ([], False, 0, 0)
        runs = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isascii() and s[i].isdigit():
                j = i
                while j < n and s[j].isascii() and s[j].isdigit():
                    j += 1
                runs.append(("num", int(s[i:j])))
                i = j
            else:
                runs.append(("txt", s[i:j]))
                i = j
        has_num = any(t == "num" for _, t in runs)
        return (runs, has_num, len(runs), s)

    return sorted(strings, key=_key)
