import functools

def natural_sort_strings(arr):
    key_parts = []
    for s in arr:
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('number', int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not s[j].isdigit():
                    j += 1
                tokens.append(('text', s[i:j]))
                i = j
        key_parts.append((tokens, s))

    def compare_keys(a, b):
        tokens_a, orig_a = a
        tokens_b, orig_b = b
        min_len = min(len(tokens_a), len(tokens_b))
        for i in range(min_len):
            kind_a, val_a = tokens_a[i]
            kind_b, val_b = tokens_b[i]
            if kind_a != kind_b:
