                elif val_a > val_b:
                    return 1
        if len(tokens_a) < len(tokens_b):
            return -1
        elif len(tokens_a) > len(tokens_b):
            return 1
        return 0

    indexed = list(enumerate(arr))
    sorted_pairs = sorted(indexed, key=functools.cmp_to_key(lambda x, y: compare_keys(key_parts[x[0]], key_parts[y[0]])))
